`,e.jsxs(s.p,{children:["The chart mounts configured Secrets read-only into every AMQP-consuming workload: the CA certificate under ",e.jsx(s.code,{children:"/etc/lamassu/amqp/ca"})," and the client certificate and key under ",e.jsx(s.code,{children:"/etc/lamassu/amqp/client"}),". The mounted file names are always ",e.jsx(s.code,{children:"ca.crt"}),", ",e.jsx(s.code,{children:"tls.crt"})," and ",e.jsx(s.code,{children:"tls.key"})," — the ",e.jsx(s.code,{children:"certificateKey"})," and ",e.jsx(s.code,{children:"privateKeyKey"})," values rename only the Secret data keys, never the on-disk paths. The client private key is mounted with restrictive permissions (",e.jsx(s.code,{children:"defaultMode: 0440"}),"; the CA volume uses ",e.jsx(s.code,{children:"0444"}),"), which works because the chart adds ",e.jsx(s.code,{children:"fsGroup"})," to the pod security context when ",e.jsx(s.code,{children:"amqp.client.secretName"})," is set — the chart's default pod security context already sets ",e.jsx(s.code,{children:"fsGroup: 65532"})," for every service pod, so this top-up applies only when an explicit ",e.jsx(s.code,{children:"podSecurityContext"})," without ",e.jsx(s.code,{children:"fsGroup"})," was overridden and an AMQP client Secret is configured — and it uses the container ",e.jsx(s.code,{children:"runAsGroup"})," (default ",e.jsx(s.code,{children:"65532"}),") when ",e.jsx(s.code,{children:"fsGroup"})," is not already set."]}),`
`,e.jsxs(s.p,{children:["Both Secret options require ",e.jsx(s.code,{children:"amqp.tls: true"}),": ",e.jsx(s.code,{children:"values.schema.json"})," rejects a non-empty ",e.jsx(s.code,{children:"secretName"})," when ",e.jsx(s.code,{children:"tls"})," is false, rejects unknown keys and rejects data-key names outside ",e.jsx(s.code,{children:"^[A-Za-z0-9._-]+$"}),". The referenced Secret must exist in the release namespace or the consuming pods fail to start."]}),`
