`,e.jsx(t,{type:"warn",title:"Set the AMQP port before upgrading",children:e.jsxs(s.p,{children:["Per the migration guide ",e.jsx(s.code,{children:"charts/lamassu/CHANGELOG/3.8.0->4.0.0.md"}),": in 3.8.0 ",e.jsx(s.code,{children:"amqp.tls"})," was not applied and event-bus clients used plaintext AMQP; from 4.0.0, ",e.jsx(s.code,{children:"amqp.tls: true"})," switches them to AMQPS. Set ",e.jsx(s.code,{children:"amqp.port"})," to the broker TLS listener before upgrading, or set ",e.jsx(s.code,{children:"amqp.tls: false"})," to keep plaintext AMQP. ",e.jsx(s.code,{children:"amqp.tls: false"})," sends the broker credentials and all event-bus traffic in cleartext."]})}),`
